<?php
require_once __DIR__.'/customer_area_common.php';
$companyQ=$pdo->prepare('SELECT company_name FROM companies WHERE id=?');$companyQ->execute([$company_id]);$companyName=(string)$companyQ->fetchColumn();$account=ca_account($pdo,$company_id);if(!$account){header('Location: customer_auth.php?account=login');exit;}$customerId=(int)$account['customer_id'];$page=$_GET['page']??'home';if(!in_array($page,['home','messenger','history','cart'],true))$page='home';
// Session cart is preserved from public marketplace; bind it to this company's customer account after login.
if(!isset($_SESSION['marketplace_cart'])||!is_array($_SESSION['marketplace_cart']))$_SESSION['marketplace_cart']=[];
if((int)($_SESSION['marketplace_cart_loaded_account']??0)!==(int)$account['account_id']){try{$q=$pdo->prepare("SELECT id FROM marketplace_carts WHERE company_id=? AND customer_account_id=? AND cart_status='active' LIMIT 1");$q->execute([$company_id,$account['account_id']]);$cartId=(int)$q->fetchColumn();if($cartId){$it=$pdo->prepare('SELECT line_key,item_type,item_id,quantity,service_note,required_work,preferred_date,service_location FROM marketplace_cart_items WHERE cart_id=? AND company_id=?');$it->execute([$cartId,$company_id]);while($r=$it->fetch(PDO::FETCH_ASSOC)){$key=$r['item_type']==='product'?'product-'.$r['item_id']:'service-'.substr($r['line_key'],0,32);if($r['item_type']==='product')$_SESSION['marketplace_cart'][$key]=['type'=>'product','id'=>(int)$r['item_id'],'quantity'=>(int)$r['quantity']];else $_SESSION['marketplace_cart'][$key]=['type'=>'service','id'=>(int)$r['item_id'],'quantity'=>(int)$r['quantity'],'line_key'=>$r['line_key'],'service_note'=>$r['service_note'],'required_work'=>$r['required_work'],'preferred_date'=>$r['preferred_date'],'service_location'=>$r['service_location']];}}$_SESSION['marketplace_cart_loaded_account']=(int)$account['account_id'];}catch(Throwable $e){error_log('Customer cart restore: '.$e->getMessage());}}
$pdo->exec("CREATE TABLE IF NOT EXISTS marketplace_customer_otps (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, company_id INT NOT NULL, customer_id INT NOT NULL, account_id BIGINT UNSIGNED NOT NULL, email VARCHAR(190) NOT NULL, otp_hash VARCHAR(255) NOT NULL, purpose ENUM('register','login') NOT NULL, expires_at DATETIME NOT NULL, attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, KEY idx_customer_otp (company_id,email,purpose,expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!ca_check_csrf()){ca_flash('error','Security token expired.');header('Location: customer_dashboard.php?page='.$page);exit;}$act=$_POST['action']??'';
 if($act==='cart_update'){$key=(string)($_POST['key']??'');$qty=(int)($_POST['quantity']??1);if(isset($_SESSION['marketplace_cart'][$key])){if($qty<=0)unset($_SESSION['marketplace_cart'][$key]);else $_SESSION['marketplace_cart'][$key]['quantity']=min(99,$qty);}ca_flash('success','Cart updated.');header('Location: customer_dashboard.php?page=cart');exit;}
 if($act==='cart_remove'){unset($_SESSION['marketplace_cart'][(string)($_POST['key']??'')]);ca_flash('success','Item removed.');header('Location: customer_dashboard.php?page=cart');exit;}
 if($act==='chat_send'){$conversation=(int)($_POST['conversation_id']??0);$body=trim((string)($_POST['body']??''));$verify=$pdo->prepare("SELECT cp.id FROM chat_participants cp JOIN chat_conversations cc ON cc.id=cp.conversation_id WHERE cp.conversation_id=? AND cp.user_id=? AND cp.participant_type='customer' AND cc.company_id=? AND cp.left_at IS NULL LIMIT 1");$verify->execute([$conversation,$customerId,$company_id]);if($verify->fetchColumn()&&$body!==''){$pdo->prepare("INSERT INTO chat_messages(conversation_id,sender_id,sender_type,message_type,body,created_at) VALUES(?,?,'customer','text',?,NOW())")->execute([$conversation,$customerId,mb_substr($body,0,5000)]);$pdo->prepare('UPDATE chat_conversations SET updated_at=NOW() WHERE id=? AND company_id=?')->execute([$conversation,$company_id]);}header('Location: customer_dashboard.php?page=messenger&conversation='.$conversation);exit;}
}
// Create/reuse direct customer conversations with head-office admin and the customer's branch manager/admin.
if($page==='messenger'){
 $staffQ=$pdo->prepare("SELECT id,username,role,location_id FROM users WHERE company_id=? AND status='active' AND (LOWER(role) LIKE '%head%administrator%' OR LOWER(role) LIKE '%branch%manager%' OR LOWER(role) LIKE '%branch%administrator%' OR LOWER(role) LIKE '%administrator%') ORDER BY CASE WHEN LOWER(role) LIKE '%head%' THEN 0 ELSE 1 END,id");$staffQ->execute([$company_id]);$staff=$staffQ->fetchAll(PDO::FETCH_ASSOC);
 foreach($staff as $u){if(stripos($u['role'],'head')===false&&(int)$u['location_id']!==(int)$account['location_id'])continue;$find=$pdo->prepare("SELECT cc.id FROM chat_conversations cc JOIN chat_participants cp ON cp.conversation_id=cc.id AND cp.user_id=? AND cp.participant_type='employee' JOIN chat_participants cu ON cu.conversation_id=cc.id AND cu.user_id=? AND cu.participant_type='customer' WHERE cc.company_id=? AND cc.conversation_type='direct' LIMIT 1");$find->execute([(int)$u['id'],$customerId,$company_id]);$conv=(int)$find->fetchColumn();if(!$conv){$pdo->beginTransaction();$pdo->prepare("INSERT INTO chat_conversations(company_id,location_id,conversation_type,title,created_by,created_by_type,created_at,updated_at) VALUES(?,?,'direct',?,?, 'customer',NOW(),NOW())")->execute([$company_id,(int)$account['location_id'],'Customer: '.$account['fullname'], $customerId]);$conv=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO chat_participants(conversation_id,user_id,participant_type,participant_role,joined_at) VALUES(?,?,'customer','member',NOW()),(?,?,'employee','admin',NOW())")->execute([$conv,$customerId,$conv,(int)$u['id']]);$pdo->commit();}}
}
$conversationId=(int)($_GET['conversation']??0);$conversations=[];$messages=[];if($page==='messenger'){$q=$pdo->prepare("SELECT cc.id,cc.title,cc.location_id,cc.updated_at,MAX(CASE WHEN cp.participant_type='employee' THEN u.username END) staff_name,MAX(CASE WHEN cp.participant_type='employee' THEN u.role END) staff_role FROM chat_conversations cc JOIN chat_participants mine ON mine.conversation_id=cc.id AND mine.user_id=? AND mine.participant_type='customer' AND mine.left_at IS NULL LEFT JOIN chat_participants cp ON cp.conversation_id=cc.id AND cp.participant_type='employee' LEFT JOIN users u ON u.id=cp.user_id AND u.company_id=cc.company_id WHERE cc.company_id=? GROUP BY cc.id ORDER BY cc.updated_at DESC");$q->execute([$customerId,$company_id]);$conversations=$q->fetchAll(PDO::FETCH_ASSOC);if(!$conversationId&&$conversations)$conversationId=(int)$conversations[0]['id'];if($conversationId){$v=$pdo->prepare("SELECT id FROM chat_participants WHERE conversation_id=? AND user_id=? AND participant_type='customer' AND left_at IS NULL");$v->execute([$conversationId,$customerId]);if($v->fetchColumn()){$m=$pdo->prepare("SELECT cm.*,CASE WHEN cm.sender_type='customer' THEN ? ELSE COALESCE(u.username,'Company admin') END sender_name FROM chat_messages cm LEFT JOIN users u ON cm.sender_type='employee' AND u.id=cm.sender_id WHERE cm.conversation_id=? AND cm.deleted_for_everyone=0 ORDER BY cm.id ASC LIMIT 300");$m->execute([$account['fullname'],$conversationId]);$messages=$m->fetchAll(PDO::FETCH_ASSOC);}}}
$history=[];if($page==='history'){$q=$pdo->prepare("SELECT mo.id,mo.order_number,mo.product_subtotal,mo.grand_total,mo.order_status,mo.created_at,moi.item_type,moi.item_name,moi.quantity,moi.unit_price,moi.line_total,moi.item_status,moi.pricing_type,moi.quotation_status,moi.service_note,moi.required_work,moi.preferred_date,moi.service_location FROM marketplace_orders mo LEFT JOIN marketplace_order_items moi ON moi.order_id=mo.id AND moi.company_id=mo.company_id WHERE mo.company_id=? AND mo.customer_id=? ORDER BY mo.id DESC,moi.id ASC");$q->execute([$company_id,$customerId]);$history=$q->fetchAll(PDO::FETCH_ASSOC);}
$cart=$_SESSION['marketplace_cart'];$cartCount=0;foreach($cart as $it)$cartCount+=(int)($it['quantity']??1);
ca_layout_start(ucfirst($page),$companyName);?><main class="wrap"><div class="layout"><?php ca_nav($page);?><section>
<?php if($page==='home'):?><div class="panel"><h1>Welcome, <?=ca_h($account['fullname'])?></h1><p class="muted">Your customer account gives you one place to communicate with the company, review purchases and manage your shopping cart.</p></div><div class="grid"><div class="stat"><span class="muted">Purchase records</span><b><?php $q=$pdo->prepare('SELECT COUNT(*) FROM marketplace_orders WHERE company_id=? AND customer_id=?');$q->execute([$company_id,$customerId]);echo (int)$q->fetchColumn();?></b></div><div class="stat"><span class="muted">Items in cart</span><b><?=$cartCount?></b></div><div class="stat"><span class="muted">Account email</span><b style="font-size:14px;overflow-wrap:anywhere"><?=ca_h($account['login_email'])?></b></div></div><div class="panel"><h3>Quick access</h3><p><a class="btn" href="customer_dashboard.php?page=messenger">Open messenger</a> <a class="btn gold" href="customer_dashboard.php?page=history">View purchase history</a> <a class="btn light" href="marketplace.php">Browse marketplace</a></p></div>
<?php elseif($page==='history'):?><div class="panel"><h1>Purchase history</h1><p class="muted">Product orders and service/quotation requests submitted to this company.</p><?php if(!$history):?><p>No marketplace orders or service requests found yet.</p><?php else:?><div class="tablewrap"><table class="table"><thead><tr><th>Order</th><th>Date</th><th>Item</th><th>Type</th><th>Qty</th><th>Amount</th><th>Status</th></tr></thead><tbody><?php foreach($history as $r):?><tr><td><?=ca_h($r['order_number'])?></td><td><?=ca_h($r['created_at'])?></td><td><?=ca_h($r['item_name']??'—')?><?php if($r['item_type']==='service'&&($r['service_note']||$r['required_work'])):?><div class="small">Note: <?=ca_h($r['service_note'])?> <?=ca_h($r['required_work'])?></div><?php endif;?></td><td><?=ca_h(ucfirst($r['item_type']??''))?></td><td><?= (int)($r['quantity']??0)?></td><td>₦<?=number_format((float)($r['line_total']??0),2)?></td><td><?=ca_h($r['item_status']??$r['order_status'])?><?php if(($r['pricing_type']??'')==='quotation'):?><div class="small">Quotation: <?=ca_h($r['quotation_status'])?></div><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></div>
<?php elseif($page==='cart'):?><div class="panel"><h1>My cart</h1><p class="muted">Your pre-login session cart has been carried into your customer account.</p><?php if(!$cart):?><p>Your cart is empty. <a href="marketplace.php">Browse products and services</a>.</p><?php else:?><div class="tablewrap"><table class="table"><thead><tr><th>Item</th><th>Type</th><th>Quantity</th><th>Action</th></tr></thead><tbody><?php foreach($cart as $key=>$it):?><tr><td><?=ca_h(($it['type']??'')==='product'?'Product #':'Service #').(int)$it['id']?><?php if(($it['type']??'')==='service'):?><div class="small"><?=ca_h($it['service_note']??'')?></div><?php endif;?></td><td><?=ca_h(ucfirst($it['type']??''))?></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=ca_h(ca_csrf())?>"><input type="hidden" name="action" value="cart_update"><input type="hidden" name="key" value="<?=ca_h($key)?>"><input type="number" name="quantity" min="0" max="99" value="<?=(int)$it['quantity']?>" style="width:75px"><button class="btn light">Update</button></form></td><td><form method="post"><input type="hidden" name="csrf_token" value="<?=ca_h(ca_csrf())?>"><input type="hidden" name="action" value="cart_remove"><input type="hidden" name="key" value="<?=ca_h($key)?>"><button class="btn light">Remove</button></form></td></tr><?php endforeach;?></tbody></table></div><p><a class="btn gold" href="marketplace.php?checkout=1">Proceed to checkout</a> <a class="btn light" href="marketplace.php">Continue shopping</a></p><?php endif;?></div>
<?php else:?><div class="panel"><h1>Customer messenger</h1><p class="muted">Chat with the company's head-office administrator and your branch administrator.</p><div class="layout" style="grid-template-columns:230px 1fr"><div><?php foreach($conversations as $c):?><a class="btn light" style="display:block;margin:6px 0" href="?page=messenger&conversation=<?=(int)$c['id']?>"><?=ca_h($c['staff_name']?:$c['title']?:'Company admin')?><div class="small"><?=ca_h($c['staff_role']??'')?></div></a><?php endforeach;?></div><div><div class="chatbox" id="chatbox"><?php if(!$messages):?><p class="muted">Start a conversation with the company.</p><?php endif;?><?php foreach($messages as $m):?><div class="msg <?=$m['sender_type']==='customer'?'mine':''?>"><b><?=ca_h($m['sender_name'])?></b><div><?=nl2br(ca_h($m['body']??''))?></div><div class="small"><?=ca_h($m['created_at'])?></div></div><?php endforeach;?></div><?php if($conversationId):?><form method="post" style="display:flex;gap:8px;margin-top:12px"><input type="hidden" name="csrf_token" value="<?=ca_h(ca_csrf())?>"><input type="hidden" name="action" value="chat_send"><input type="hidden" name="conversation_id" value="<?=$conversationId?>"><input name="body" placeholder="Write a message..." required maxlength="5000" style="flex:1;padding:12px;border:1px solid #dce3e9;border-radius:9px"><button class="btn gold">Send</button></form><?php endif;?></div></div></div></div><?php endif;?></section></div></main><script>const c=document.getElementById('chatbox');if(c)c.scrollTop=c.scrollHeight;</script></body></html>
